findings=[
 dict(id='AUD-01',severity='HIGH',phase='1,5',status='FAIL',file='services/api/app/api/deps.py',line=62,title='Concurrent chat exhausts the database pool before admission control',root='The request dependency holds an authenticated DB session while find_conversation and generation preparation open additional sessions. The limiter runs after the second lookup. Default pool size 5 plus overflow 5 is exhausted by ten simultaneous request-scoped sessions.',impact='Authenticated callers can cause request stalls and HTTP 500s; shared per-process pool pressure can degrade other tenants. No cross-tenant data disclosure was observed.',repro='Run AUDIT_CONFIRM_POOL=1 with the staged-performance audit test. Fresh confirmation: 9/10 HTTP 500; QueuePool size 5 overflow 5 timeout 30 seconds. Original 10/50/100 stages all returned HTTP 500.',evidence='evidence/performance.json; evidence/performance_confirmation.json; evidence/pool_regression.log',fix='Release request authentication transactions before slow chat work, avoid nested pool checkouts, and apply admission/backpressure before acquiring scarce DB sessions. Bound pool wait and map overload to controlled 429/503. Re-test cross-tenant fairness.',test='Ten concurrent chat requests with default pool must complete or receive documented admission limits, with zero 500s. Include a second tenant health/read request during saturation.'),
 dict(id='AUD-02',severity='MEDIUM',phase='4,5',status='FAIL',file='services/api/app/rag/retrieval.py',line=187,title='Citation eligibility can include a source absent from the rendered prompt',root='render_context counts escaped characters and may stop before rendering all selected chunks. assemble returns the original selected list; citations_for validates against that list, not rendered sources.',impact='An answer marker can receive apparently valid provenance for evidence the model never saw. This is not a cross-tenant leak: affected chunks are still tenant-scoped.',repro='Supply first passage consisting of 2,500 ampersands and a second passage. With a 16,000-byte prompt budget, escaping expands the first passage past render_context\'s 12,000-character ceiling. Source 2 is absent from the prompt, but Answer [2] still produces its citation.',evidence='evidence/security_regressions.log; services/api/tests/unit/audit/test_prompt_evidence.py:26',fix='Return the exact rendered source set/IDs from prompt assembly and validate citation markers against it. Budget escaped content consistently.',test='test_citations_must_only_reference_sources_actually_rendered currently fails; cover HTML expansion, metadata overhead and partially omitted sources.'),
 dict(id='AUD-03',severity='MEDIUM',phase='1,4',status='FAIL',file='services/api/app/core/config.py',line=265,title='Production permits HTTP embedding endpoints',root='Production guards reject hash embeddings but do not require HTTPS for EMBEDDING_BASE_URL. OpenAICompatibleEmbedder accepts http and attaches bearer credentials plus document content.',impact='If an operator configures HTTP in production, embedding keys and customer text can travel without TLS. Current local configuration contains no real key; no actual credential disclosure was performed or observed.',repro='The audit production-settings test supplies an HTTP embedding base URL and otherwise valid synthetic production settings. No ValidationError is raised.',evidence='evidence/security_regressions.log; services/api/app/rag/embeddings.py:108',fix='Require HTTPS in production/staging as appropriate, reject credentials/query fragments in provider URLs, and disable or strictly validate cross-host redirects.',test='test_production_embedding_transport_must_require_https currently fails. Add redirect/certificate validation tests with fixture credentials.'),
 dict(id='AUD-04',severity='MEDIUM',phase='1,2,6',status='PARTIALLY_IMPLEMENTED',file='services/api/Dockerfile',line=45,title='Production proxy headers trust every peer',root='Runtime uvicorn command uses --forwarded-allow-ips "*".',impact='If the API is reachable outside a strictly trusted proxy boundary, forged forwarded addresses can evade IP limits and distort audit IP metadata. Token/org limits remain independent barriers. Actual public deployment topology was not tested.',repro='Static: inspect the runtime CMD. In a disposable deployment, send differing X-Forwarded-For values directly and observe request.client-derived limits.',evidence='services/api/Dockerfile:45; services/api/app/core/request_meta.py:35; docs/PHASE2_SECURITY_REVIEW.md',fix='Restrict trusted proxy CIDRs and deny direct ingress; add a deployment assertion and forged-header regression.',test='Direct untrusted connections cannot choose the limiter IP; trusted proxy chains resolve the intended client.'),
 dict(id='AUD-05',severity='MEDIUM',phase='4',status='PARTIALLY_IMPLEMENTED',file='services/api/app/workers/celery_app.py',line=26,title='Document parser lacks hard worker time/resource isolation',root='Format and extraction limits exist, but parsing runs in-process and tasks have no configured soft/hard execution deadlines. Worker containers have no explicit resource limits in Compose.',impact='A pathological but size-compliant document could monopolize ingestion workers or memory. This is a static hardening gap; an exploit PDF/worker kill was not executed.',repro='Inspect task configuration and extract_stored/parse paths; test with a bounded slow parser fixture rather than an unbounded malicious payload.',evidence='services/api/app/rag/extract.py:90; services/api/app/workers/tasks/ingest.py:33; docker-compose.yml',fix='Add bounded parsing in a constrained process plus worker soft/hard deadlines, memory/CPU limits and safe failure recovery.',test='A fixture parser exceeding its wall-clock budget is terminated, marks the job safely and does not starve another tenant.'),
 dict(id='AUD-06',severity='LOW',phase='3,5',status='PARTIALLY_IMPLEMENTED',file='apps/web/src/components/conversations/conversations-screen.tsx',line=61,title='Conversation inbox still displays a placeholder empty state',root='The screen fetches chatbot options but does not load stored conversations. Filters are disabled and the empty state is unconditional.',impact='Stored public/widget conversations cannot be reviewed from this inbox despite the implemented API and playground history. Advanced Phase 7 analytics are outside this audit; the present placeholder should be labelled accurately.',repro='Persist a conversation, open Conversations, inspect the component/request behavior; no transcript query is made by this screen.',evidence='apps/web/src/components/conversations/conversations-screen.tsx:14; baseline conversation persistence tests',fix='Within the agreed MVP scope, surface existing conversation data or explicitly communicate the limitation; do not claim the inbox complete.',test='After saving a widget conversation, inbox refresh displays it or an explicit unavailable-feature state.'),
 dict(id='AUD-07',severity='LOW',phase='6',status='PARTIALLY_IMPLEMENTED',file='apps/widget/src/loader.ts',line=41,title='Repeated installation has no deduplication or teardown',root='Every script execution appends another iframe and window message listener. There is no per-key instance registry or cleanup API.',impact='Accidental duplicate tags or SPA remounts can create overlapping launchers and extra session issuance. Different-key isolation passed; repeated same-key behavior has only static evidence here.',repro='Install the same script/key twice and inspect iframe/listener count; the source contains an unconditional append.',evidence='apps/widget/src/loader.ts:4,41',fix='Define idempotent default initialization with an explicit multi-instance opt-in and remove listeners/frames during teardown.',test='Repeated initialization of one key yields the documented instance count and no extra stale listeners.'),
]
